/* Shared visual refinements for the standalone admin. */
farms[1].image="data:image/jpeg;base64,";
farms[2].image="data:image/jpeg;base64,";
const extraFarms=[['Almas Dairy','Stockholm','Dairy & cheese',21,0],['Bjäre Chicken Farm','Båstad','Meat & poultry',16,1],['EcoRoots Farm','Västerås','Vegetables & roots',28,2],['Green Harvest Organics','Gothenburg','Pantry',19,2],['Pleasant Valley','Uppsala','Vegetables & roots',26,0]];
for(const [name,city,category,products,imageIndex] of extraFarms){if(!farms.some(f=>f.name===name))farms.push({name,city,category,products,commission:12,status:'Active',image:farms[imageIndex].image,email:name.toLowerCase().replace(/[^a-z]/g,'')+'@example.com',phone:'+46 70 000 1010',postal:'111 57',address:'18 Meadow Lane'});}
const prePolishShell=shell;
shell=function(content,title){prePolishShell(content,title);decorateAdmin();};

function illustratedFood(name){
 name=({Dairy:'Dairy & cheese',Meat:'Meat & poultry',Vegetables:'Vegetables & roots',Honey:'Pantry'})[name]||name;
 const shapes={
 'Fruits':'<path fill="#edbda3" d="M22 15C8 7 5 24 14 34q8 5 9 0c13 5 18-24 5-21z"/><path fill="#adcda0" d="M23 13q-1-11 10-9-1 10-10 9Z"/><path d="M22 16v-7M13 21q-2 6 2 9"/>',
 'Herbs':'<path d="M15 38 29 6"/><path fill="#adcda0" d="M23 20Q9 19 12 9q12 1 11 11ZM19 29Q5 29 7 18q12 1 12 11ZM22 24q14-1 13-11-12 0-13 11ZM16 35q14 2 15-8-12-2-15 8ZM28 13q10-3 7-11-10 2-7 11Z"/>',
 'Nuts':'<path fill="#edbda3" d="M24 5C4 11 4 32 17 31S33 10 24 5Z"/><path fill="#f3d780" d="M32 17C13 20 14 39 25 37S40 23 32 17Z"/><path d="M24 10Q12 20 14 27M31 22q-10 5-9 11"/>',
 'Grains':'<path d="M22 40V9"/><path fill="#f3d780" d="M22 15q-12 0-11-10 11 1 11 10Zm0 10q-12 0-11-10 11 1 11 10Zm0 10q-12 0-11-10 11 1 11 10Zm0-15q12 0 11-10-11 1-11 10Zm0 10q12 0 11-10-11 1-11 10Z"/><path fill="#adcda0" d="M22 11q-7-7 0-10 7 5 0 10Z"/>',
 'Vegetables & roots':'<path fill="#adcda0" d="M24 16C17 12 11 23 7 34c12-4 23-10 21-15z"/><path d="m24 16 8-10m-6 10 9-3m-13 2 1-10M13 24l5 3m-1-9 6 3"/>',
 'Meat & poultry':'<path fill="#edbda3" d="M5 21c8-12 20-12 27 0-7 12-19 12-27 0Z"/><path fill="#a8cbc0" d="m32 21 7-8v16z"/><path d="M21 11c-4 7-4 13 0 20"/><circle cx="12" cy="19" r="1" fill="#254f45" stroke="none"/>',
 'Dairy & cheese':'<path fill="#f3d780" d="M5 20 31 9l7 11v12H5z"/><path d="M5 20h33M31 9l-5 3m6 8v12"/><circle cx="13" cy="26" r="1.5" fill="#fff0bd"/><circle cx="24" cy="26" r="1.5" fill="#fff0bd"/><path d="m24 14 3 2"/>',
 'Pantry':'<path fill="#f1d687" d="M12 15h19v5l3 5v12H9V25l3-5z"/><path fill="#a9cbb4" d="M12 10h19v5H12z"/><path d="M10 25h23M10 32h23m-2-17 6-9m-3 0 6 4m-8-1 6 4"/><path fill="#edbda3" d="M23 25c-5 6-5 8-1 8s4-3 1-8Z"/>',
 'Drinks':'<path fill="#a9cbb4" d="M16 5h12v7l5 8v17H11V20l5-8z"/><path fill="#f2d786" d="M11 23h22v10H11z"/><path d="M16 9h12"/><path fill="#edbda3" d="M22 25c-5 5-4 7 0 7s5-2 0-7Z"/>'
 };
 return '<svg class="food-illustration" viewBox="0 0 44 44" fill="none" stroke="#254f45" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(shapes[name]||shapes.Pantry)+'</svg>';
}

function decorateAdmin(){
 if(state.page==='categories'){document.querySelector('main table')?.classList.add('category-directory');document.querySelectorAll('.category-directory tbody tr').forEach(row=>{const holder=row.querySelector('.category-icon');if(holder)holder.innerHTML=illustratedFood(row.querySelector('strong').textContent.trim());});}
 document.querySelectorAll('.top-right .dot,.top-right .live-label,.top-right .date').forEach(el=>el.remove());
 document.querySelectorAll('.stat').forEach((el,i)=>{if(!el.querySelector('.mini-icon'))el.insertAdjacentHTML('beforeend',`<div class="mini-icon">${icon(['money','orders','reports','calendar'][i%4])}</div>`);});
 const tabIcons={'All orders':'orders','Confirmed':'check','Preparing':'box','In transit':'truck','Delivered':'check','Sales summary':'reports','Sales report':'orders','Monthly report':'calendar'};
 document.querySelectorAll('.tabs button').forEach(el=>{const key=Object.keys(tabIcons).find(k=>el.textContent.trim().startsWith(k));if(key&&!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(tabIcons[key]));});
 document.querySelectorAll('.panel-title h2').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(/journey/i.test(el.textContent)?'truck':/items/i.test(el.textContent)?'box':/city/i.test(el.textContent)?'pin':/sales/i.test(el.textContent)?'reports':'leaf'));});
 if(state.page==='customers'&&!state.detail&&!document.querySelector('.contact-directory')){const table=document.querySelector('main table');if(table){table.classList.add('customer-table');table.querySelector('thead th:last-child').textContent='Actions';table.querySelectorAll('tbody tr').forEach(tr=>{const city=tr.children[1];city.innerHTML=`<span class="location-label">${icon('pin')}${city.textContent}</span>`;const b=tr.querySelector('button');b.insertAdjacentHTML('beforeend',icon('arrow'));});}}
}
const prePolishModal=openModal;
openModal=function(title,body,footer=''){
 if(title==='Your workspace updates'){
 const count=orders.filter(o=>o.status==='Confirmed').length,reviewCount=reviews.filter(r=>r.status==='Pending').length;
 body=`<section><p class="update-intro">A quick look at what needs your attention today.</p><article class="update-card"><span class="update-icon">${icon('box')}</span><div><h3>${count} ${count===1?'order':'orders'} ready to prepare</h3><p>Fresh picks are waiting. Help your farm partners get the next orders on their way.</p><button class="update-link" data-update="orders">Review orders ${icon('arrow')}</button></div></article><article class="update-card"><span class="update-icon">${icon('reviews')}</span><div><h3>${reviewCount} ${reviewCount===1?'review':'reviews'} awaiting moderation</h3><p>Your community has something to share. Take a moment to review their feedback.</p><button class="update-link" data-update="reviews">View feedback ${icon('arrow')}</button></div></article></section><footer><small style="margin-right:auto">You’re keeping good things moving.</small>${btn('Done','modal-close','','primary')}</footer>`;
 }
 prePolishModal(title,body,footer);
 const kind=/category/i.test(title)?'categories':/updates/i.test(title)?'bell':/delivery/i.test(title)?'truck':/status/i.test(title)?'box':/farm/i.test(title)?'farms':'customers';
 $('#modal-title').insertAdjacentHTML('afterbegin',`<span class="dialog-heading-icon">${icon(kind)}</span>`);
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-update]');if(!b)return;closeModal();if(b.dataset.update==='orders'){state.tab='Confirmed';state.query='';state.payment='All payments';state.start='';state.end='';state.pageNum=1;}go(b.dataset.update);});
const originalLoginView=login;
login=function(){originalLoginView();document.querySelector('.login-form').insertAdjacentHTML('afterbegin','<div class="login-lock">'+icon('leaf')+'</div>');};
render();
